  "nitrate with a PDE5 inhibitor can drop blood pressure dangerously": { "es": "un nitrato con un inhibidor de la PDE5 puede bajar la presión arterial de forma peligrosa", "pt": "nitrato com um inibidor da PDE5 pode reduzir perigosamente a pressão arterial", "fr": "un dérivé nitré associé à un inhibiteur de la PDE5 peut faire chuter dangereusement la tension" },
  "raises bleeding risk with a blood thinner": { "es": "aumenta el riesgo de sangrado con un anticoagulante", "pt": "aumenta o risco de sangramento com um anticoagulante", "fr": "augmente le risque de saignement avec un anticoagulant" },
  "can raise blood pressure and strain the kidneys with this blood-pressure medicine": { "es": "puede subir la presión arterial y sobrecargar los riñones con este medicamento para la presión", "pt": "pode elevar a pressão arterial e sobrecarregar os rins com este remédio para a pressão", "fr": "peut augmenter la tension et solliciter les reins avec ce médicament contre l’hypertension" },
  "combined with a sedative it can stop breathing": { "es": "combinado con un sedante puede detener la respiración", "pt": "combinado com um sedativo pode parar a respiração", "fr": "associé à un sédatif, il peut arrêter la respiration" },
