  "No items in this filter.": { "es": "No hay artículos en este filtro.", "pt": "Não há itens neste filtro.", "fr": "Aucun article dans ce filtre." },
  "Changes are shared with everyone on this mission code.": { "es": "Los cambios se comparten con todos los que usan este código de misión.", "pt": "As alterações são compartilhadas com todos que usam este código de missão.", "fr": "Les modifications sont partagées avec tous ceux qui utilisent ce code de mission." },
  "Local mode: the list is stored on this device. Connect the database to share it with the crew.": { "es": "Modo local: la lista se guarda en este dispositivo. Conecta la base de datos para compartirla con la tripulación.", "pt": "Modo local: a lista fica salva neste dispositivo. Conecte o banco de dados para compartilhá-la com a tripulação.", "fr": "Mode local : la liste est stockée sur cet appareil. Connectez la base de données pour la partager avec l’équipage." },
  "Download as CSV": { "es": "Descargar como CSV", "pt": "Baixar como CSV", "fr": "Télécharger en CSV" },
  "Update item": { "es": "Actualizar artículo", "pt": "Atualizar item", "fr": "Mettre à jour l’article" },
  "Add an item": { "es": "Agregar un artículo", "pt": "Adicionar um item", "fr": "Ajouter un article" },
  "Change what is on board. The crew sees the update.": { "es": "Cambia lo que hay a bordo. La tripulación verá la actualización.", "pt": "Altere o que há a bordo. A tripulação verá a atualização.", "fr": "Modifiez ce qui est à bord. L’équipage voit la mise à jour." },
  "Something the ship carries that the crew may need.": { "es": "Algo que lleva la nave y que la tripulación puede necesitar.", "pt": "Algo que a nave carrega e que a tripulação pode precisar.", "fr": "Quelque chose que le vaisseau transporte et dont l’équipage peut avoir besoin." },
  "Close": { "es": "Cerrar", "pt": "Fechar", "fr": "Fermer" },
