  "Unit": { "es": "Unidad", "pt": "Unidade", "fr": "Unité" },
  "Quantity on board": { "es": "Cantidad a bordo", "pt": "Quantidade a bordo", "fr": "Quantité à bord" },
  "Warn when at or below": { "es": "Avisar cuando llegue o baje de", "pt": "Avisar quando estiver em ou abaixo de", "fr": "Avertir quand à ou sous" },
  "Note": { "es": "Nota", "pt": "Nota", "fr": "Note" },
