  "units, L, packs": { "es": "unidades, L, paquetes", "pt": "unidades, L, pacotes", "fr": "unités, L, paquets" },
  "Where it is stored, expiry, who to ask": { "es": "Dónde se guarda, vencimiento, a quién preguntar", "pt": "Onde fica guardado, validade, a quem perguntar", "fr": "Où c’est rangé, date de péremption, à qui demander" },
  "Cancel": { "es": "Cancelar", "pt": "Cancelar", "fr": "Annuler" },
  "Save changes": { "es": "Guardar cambios", "pt": "Salvar alterações", "fr": "Enregistrer les modifications" },
  "Create a mission": { "es": "Crear una misión", "pt": "Criar uma missão", "fr": "Créer une mission" },
  "You get a code to share. Crewmates join with it and see each other’s status.": { "es": "Recibes un código para compartir. Tus compañeros se unen con él y ven el estado de los demás.", "pt": "Você recebe um código para compartilhar. Os colegas entram com ele e veem o status uns dos outros.", "fr": "Vous recevez un code à partager. Vos coéquipiers le saisissent pour rejoindre la mission et voir l’état des autres." },
  "Mission name": { "es": "Nombre de la misión", "pt": "Nome da missão", "fr": "Nom de la mission" },
  "e.g. Orion-7": { "es": "p. ej. Orion-7", "pt": "ex.: Orion-7", "fr": "p. ex. Orion-7" },
  "Where does it take place?": { "es": "¿Dónde tiene lugar?", "pt": "Onde ela acontece?", "fr": "Où se déroule-t-elle ?" },
  "{s} · {n} mSv/day · {s}": { "es": "{s} · {n} mSv/día · {s}", "pt": "{s} · {n} mSv/dia · {s}", "fr": "{s} · {n} mSv/jour · {s}" },
  "Planned length (days)": { "es": "Duración prevista (días)", "pt": "Duração prevista (dias)", "fr": "Durée prévue (jours)" },
  "Create mission": { "es": "Crear misión", "pt": "Criar missão", "fr": "Créer la mission" },
  "Join a mission": { "es": "Unirse a una misión", "pt": "Entrar em uma missão", "fr": "Rejoindre une mission" },
  "Enter the code a crewmate shared with you.": { "es": "Ingresa el código que te compartió un compañero.", "pt": "Digite o código que um colega compartilhou com você.", "fr": "Saisissez le code qu’un coéquipier a partagé avec vous." },
  "Mission code": { "es": "Código de misión", "pt": "Código da missão", "fr": "Code de mission" },
  "You will see everyone registered on that code, and they will see your status summary.": { "es": "Verás a todos los registrados con ese código, y ellos verán el resumen de tu estado.", "pt": "Você verá todos os cadastrados nesse código, e eles verão o resumo do seu status.", "fr": "Vous verrez toutes les personnes inscrites sous ce code, et elles verront le résumé de votre état." },
  "Local mode: you will see crewmates who use this code on this device. Connect the database to join crews on other devices.": { "es": "Modo local: verás a los compañeros que usan este código en este dispositivo. Conecta la base de datos para unirte a tripulaciones en otros dispositivos.", "pt": "Modo local: você verá os colegas que usam este código neste dispositivo. Conecte o banco de dados para entrar em tripulações em outros dispositivos.", "fr": "Mode local : vous verrez les coéquipiers qui utilisent ce code sur cet appareil. Connectez la base de données pour rejoindre des équipages sur d’autres appareils." },
  "Join mission": { "es": "Unirse a la misión", "pt": "Entrar na missão", "fr": "Rejoindre la mission" },
  "Mission created": { "es": "Misión creada", "pt": "Missão criada", "fr": "Mission créée" },
  "Share this code with your crew so they can join.": { "es": "Comparte este código con tu tripulación para que puedan unirse.", "pt": "Compartilhe este código com sua tripulação para que possam entrar.", "fr": "Partagez ce code avec votre équipage pour qu’il puisse rejoindre la mission." },
  "Copy code": { "es": "Copiar código", "pt": "Copiar código", "fr": "Copier le code" },
  "Enter mission": { "es": "Entrar a la misión", "pt": "Entrar na missão", "fr": "Entrer dans la mission" },
  "{s} · Mission loadout · {s}": { "es": "{s} · Carga de la misión · {s}", "pt": "{s} · Carga da missão · {s}", "fr": "{s} · Chargement de la mission · {s}" },
  "3 per person a day (~1.8 kg)": { "es": "3 por persona al día (~1,8 kg)", "pt": "3 por pessoa por dia (~1,8 kg)", "fr": "3 par personne et par jour (~1,8 kg)" },
  "daily water comes from recycling": { "es": "el agua diaria viene del reciclaje", "pt": "a água diária vem da reciclagem", "fr": "l’eau quotidienne provient du recyclage" },
  "one every other day": { "es": "uno cada dos días", "pt": "um a cada dois dias", "fr": "un tous les deux jours" },
  "2 per person a day": { "es": "2 por persona al día", "pt": "2 por pessoa por dia", "fr": "2 par personne et par jour" },
  "no sunlight in the cabin": { "es": "no hay luz solar en la cabina", "pt": "não há luz solar na cabine", "fr": "pas de lumière du soleil dans la cabine" },
  "medical kit": { "es": "botiquín médico", "pt": "kit médico", "fr": "trousse médicale" },
