  "monitoring": { "es": "monitorización", "pt": "monitoramento", "fr": "surveillance" },
  "fasting glucose every 3 days": { "es": "glucosa en ayunas cada 3 días", "pt": "glicose em jejum a cada 3 dias", "fr": "glycémie à jeun tous les 3 jours" },
  "exam every 2 weeks": { "es": "examen cada 2 semanas", "pt": "exame a cada 2 semanas", "fr": "examen toutes les 2 semaines" },
  "monthly ECG": { "es": "ECG mensual", "pt": "ECG mensal", "fr": "ECG mensuel" },
  "eye, heart and kidney scans": { "es": "ecografías de ojo, corazón y riñón", "pt": "ultrassons de olho, coração e rim", "fr": "échographies de l’œil, du cœur et des reins" },
  "one per person": { "es": "uno por persona", "pt": "um por pessoa", "fr": "un par personne" },
  "a tube lasts ~45 days": { "es": "un tubo dura ~45 días", "pt": "um tubo dura ~45 dias", "fr": "un tube dure ~45 jours" },
  "a bottle lasts ~30 days": { "es": "un frasco dura ~30 días", "pt": "um frasco dura ~30 dias", "fr": "un flacon dure ~30 jours" },
