  "a fresh towel every 10 days": { "es": "una toalla limpia cada 10 días", "pt": "uma toalha limpa a cada 10 dias", "fr": "une serviette propre tous les 10 jours" },
  "toilet and trash": { "es": "baño y basura", "pt": "banheiro e lixo", "fr": "toilettes et déchets" },
