  "backup to the CO₂ removal system": { "es": "respaldo del sistema de eliminación de CO₂", "pt": "reserva do sistema de remoção de CO₂", "fr": "secours du système d’élimination du CO₂" },
  "one per module": { "es": "uno por módulo", "pt": "um por módulo", "fr": "un par module" },
  "fire and toxic-leak response": { "es": "respuesta a incendios y fugas tóxicas", "pt": "resposta a incêndios e vazamentos tóxicos", "fr": "intervention en cas d’incendie et de fuite toxique" },
  "depressurisation": { "es": "despresurización", "pt": "despressurização", "fr": "dépressurisation" },
  "cooling-loop leak": { "es": "fuga en el circuito de refrigeración", "pt": "vazamento no circuito de refrigeração", "fr": "fuite du circuit de refroidissement" },
  "exercise countermeasure": { "es": "contramedida de ejercicio", "pt": "contramedida de exercício", "fr": "contre-mesure par l’exercice" },
